// --- Umbrales por equipo/variable: [lo, hi] (null = ese lado no aplica) ---
const U = {
  EQ01: {
    CAUDAL:    { warning: [90, 155],  critical: [70, 175] },
    PRESION:   { warning: [3.5, 5.5], critical: [2.5, 6.5] },
    CORRIENTE: { warning: [null, 55], critical: [null, 65] },
    VIBRACION: { warning: [null, 4.5], critical: [null, 7.1] },
    ESTADO:    { critical: [0.5, null] }
  },
  EQ02: {
    TURB_IN:     { warning: [null, 15],  critical: [null, 25] },
    TURB_OUT:    { warning: [null, 1.5], critical: [null, 2.0] },
    PRES_DIF:    { warning: [null, 600], critical: [null, 800] },
    CAUDAL_FILT: { warning: [90, null],  critical: [70, null] },
    EFICIENCIA:  { warning: [80, null],  critical: [70, null] }
  },
  EQ03: {
    PH:      { warning: [6.5, 8.0], critical: [6.0, 8.5] },
    OD:      { warning: [1.5, 4.0], critical: [1.0, 5.0] },
    TEMP:    { warning: [15, 30],   critical: [10, 35] },
    CONDUCT: { warning: [null, 1800], critical: [null, 2200] },
    NIVEL:   { warning: [40, 90],   critical: [20, 95] }
  }
};

const d = msg.payload;
if (!d || d.value === undefined || !d.equipo) return null;

const partesTopic = String(msg.topic || '').split('/');
const variable = partesTopic[3] || 'NA';
const equipo = d.equipo;
const v = Number(d.value);
const reglas = (U[equipo] || {})[variable];
if (!reglas) return null;                 // variable sin umbrales definidos

function violado(rango) {
    if (!rango) return false;
    const [lo, hi] = rango;
    if (lo !== null && v < lo) return true;
    if (hi !== null && v > hi) return true;
    return false;
}

let severidad = null;
if (violado(reglas.critical)) severidad = 'critical';
else if (violado(reglas.warning)) severidad = 'warning';
if (!severidad) return null;               // dentro de rango: nada que hacer

const descripcion = equipo + '/' + variable + ' = ' + v + ' ' + (d.unit || '') +
    ' fuera de rango ' + severidad.toUpperCase() +
    ' [' + JSON.stringify(reglas[severidad]) + ']';

msg.severity = severidad;
msg.topic = '[' + severidad.toUpperCase() + '] AquaMonitor ' + equipo + '/' + variable;
msg.evento = {
    ts: d.ts || Date.now(),
    equipo: equipo,
    tag: d.tag || ['AQM','PTEF',equipo,variable].join('-'),
    event_type: 'THRESHOLD',
    description: descripcion,
    severity: severidad,
    value: v
};
msg.payload = descripcion;
return msg;

const e = msg.evento;
if (!e) return null;
function escTag(v) { return String(v).replace(/([,= ])/g, '\\$1'); }
function escStr(v) { return String(v).replace(/\\/g, '\\\\').replace(/"/g, '\\"'); }

const linea = 'events,equipo=' + escTag(e.equipo) +
    ',tag=' + escTag(e.tag) +
    ',event_type=' + escTag(e.event_type) +
    ',severity=' + escTag(e.severity) +
    ' description="' + escStr(e.description) + '",value=' + Number(e.value) +
    ' ' + e.ts;

msg.payload = linea;
msg.method = 'POST';
msg.headers = { 'Content-Type': 'text/plain; charset=utf-8' };
const token = env.get('QUESTDB_TOKEN');
if (token) msg.headers['Authorization'] = 'Bearer ' + token;
msg.url = (env.get('QUESTDB_HTTP_URL') || 'http://localhost:9000') + '/write?precision=ms';
return msg;
